INSERT INTO `articles` VALUES (1,'news','tin-noi-bat',1,'Hội nghị toàn quốc tổng kết công tác tái hòa nhập cộng đồng năm 2025','hoi-nghi-toan-quoc-tong-ket-tai-hoa-nhap-2025','Bộ Công an tổ chức hội nghị đánh giá kết quả 5 năm thực hiện công tác hỗ trợ người chấp hành xong án phạt tù tái hòa nhập cộng đồng.','<p>Sáng ngày 20/7/2025, tại Hà Nội, Bộ Công an phối hợp cùng các bộ, ngành liên quan tổ chức Hội nghị toàn quốc tổng kết công tác tái hòa nhập cộng đồng.</p><p>Hội nghị ghi nhận hơn 10.000 lượt người hoàn lương được hỗ trợ vay vốn, học nghề và giới thiệu việc làm trong giai đoạn vừa qua.</p><p>Nhiều mô hình tiêu biểu tại các địa phương đã được biểu dương, khẳng định vai trò đồng hành của cả hệ thống chính trị và toàn xã hội.</p>',NULL,'/assets/hero_banner.jpg','published',1,'2026-07-24 18:47:06','2026-07-24 20:47:06','2026-07-24 20:47:06'),(2,'news','tin-noi-bat',1,'Ra mắt Cổng thông tin điện tử hỗ trợ người hoàn lương trên toàn quốc','ra-mat-cong-thong-tin-ho-tro-nguoi-hoan-luong','Cổng thông tin Con Đường Hướng Thiện chính thức đi vào hoạt động, cung cấp tư vấn pháp lý và kết nối việc làm 24/7.','<p>Cổng thông tin điện tử Con Đường Hướng Thiện do Cục C11 - Bộ Công an chủ quản đã chính thức ra mắt.</p><p>Nền tảng cung cấp thông tin chính thống về chính sách, hỗ trợ pháp lý, kết nối đào tạo nghề và tư vấn tâm lý miễn phí cho người lầm lỡ.</p><p>Người dân có thể gửi yêu cầu trợ giúp trực tuyến hoặc gọi tới đường dây nóng 0903.480.985.</p>',NULL,'/assets/hero_banner.jpg','published',1,'2026-07-24 15:47:06','2026-07-24 20:47:06','2026-07-24 20:47:06'),(3,'news','tin-hoat-dong',2,'Khai giảng lớp đào tạo nghề miễn phí cho người chấp hành xong án phạt tù','khai-giang-lop-dao-tao-nghe-mien-phi','Lớp học nghề cơ khí và may công nghiệp thu hút hơn 80 học viên là người hoàn lương tham gia.','<p>Trung tâm Dịch vụ việc làm phối hợp cùng công an địa phương tổ chức khai giảng lớp đào tạo nghề miễn phí.</p><p>Các học viên được hỗ trợ toàn bộ học phí, tài liệu và cam kết giới thiệu việc làm sau khi tốt nghiệp.</p><p>Đây là hoạt động thiết thực giúp người hoàn lương sớm ổn định sinh kế, tái hòa nhập cộng đồng.</p>',NULL,'/assets/hero_banner.jpg','published',1,'2026-07-24 08:47:06','2026-07-24 20:47:06','2026-07-24 20:47:06'),(4,'news','tin-hoat-dong',2,'Chương trình gặp mặt, động viên người hoàn lương dịp đầu năm','chuong-trinh-gap-mat-dong-vien-nguoi-hoan-luong','Buổi gặp mặt thân mật nhằm chia sẻ, tháo gỡ khó khăn và tiếp thêm động lực cho người tái hòa nhập cộng đồng.','<p>Chương trình gặp mặt được tổ chức ấm cúng với sự tham gia của đại diện chính quyền, lực lượng công an và các doanh nghiệp nhân văn.</p><p>Nhiều phần quà và suất vốn hỗ trợ khởi nghiệp đã được trao tận tay người hoàn lương có hoàn cảnh khó khăn.</p><p>Hoạt động thể hiện sự quan tâm sâu sắc của cộng đồng đối với hành trình làm lại cuộc đời.</p>',NULL,'/assets/hero_banner.jpg','published',1,'2026-07-24 00:47:06','2026-07-24 20:47:06','2026-07-24 20:47:06'),(5,'news','tin-dia-phuong',3,'Địa phương nhân rộng mô hình tổ tự quản hỗ trợ người tái hòa nhập','dia-phuong-nhan-rong-mo-hinh-to-tu-quan','Mô hình tổ tự quản tại cơ sở giúp giám sát, giáo dục và hỗ trợ hiệu quả người chấp hành xong án phạt tù.','<p>Nhiều xã, phường đã triển khai mô hình tổ tự quản với sự tham gia của tổ dân phố, đoàn thể và gia đình.</p><p>Mô hình giúp người hoàn lương xóa bỏ mặc cảm, được tạo điều kiện tham gia lao động sản xuất tại địa phương.</p><p>Kết quả bước đầu cho thấy tỷ lệ tái phạm giảm rõ rệt tại các khu vực áp dụng.</p>',NULL,'/assets/hero_banner.jpg','published',1,'2026-07-23 16:47:06','2026-07-24 20:47:06','2026-07-24 20:47:06'),(6,'news','tin-dia-phuong',3,'Tỉnh đoàn phối hợp hỗ trợ vay vốn khởi nghiệp cho thanh niên hoàn lương','tinh-doan-ho-tro-vay-von-khoi-nghiep-thanh-nien','Chương trình tín dụng ưu đãi giúp thanh niên hoàn lương tiếp cận nguồn vốn phát triển kinh tế gia đình.','<p>Tỉnh đoàn phối hợp với Ngân hàng Chính sách xã hội triển khai gói vay ưu đãi dành cho thanh niên hoàn lương.</p><p>Nhiều mô hình chăn nuôi, trồng trọt và dịch vụ nhỏ đã hình thành từ nguồn vốn hỗ trợ này.</p><p>Đây là điểm tựa quan trọng giúp người trẻ từng lầm lỡ vững tin lập nghiệp.</p>',NULL,'/assets/hero_banner.jpg','published',1,'2026-07-23 08:47:06','2026-07-24 20:47:06','2026-07-24 20:47:06'),(7,'role_model','tam-guong-tieu-bieu',4,'Người đàn ông làm lại cuộc đời từ trại giống cây ăn quả','nguoi-dan-ong-lam-lai-cuoc-doi-tu-trai-giong','Sau khi chấp hành xong án phạt, anh N.V.T đã xây dựng trại giống cây ăn quả tạo việc làm cho nhiều lao động địa phương.','<p>Trở về từ trại giam với hai bàn tay trắng, anh N.V.T quyết tâm không đầu hàng số phận.</p><p>Được hỗ trợ vay vốn và tập huấn kỹ thuật, anh gây dựng trại giống cây ăn quả rộng gần một hecta.</p><p>Hiện trang trại tạo việc làm ổn định cho hơn 10 lao động, trong đó có những người cùng cảnh ngộ hoàn lương.</p>',NULL,'/assets/hero_banner.jpg','published',1,'2026-07-24 12:47:06','2026-07-24 20:47:06','2026-07-24 20:47:06'),(8,'role_model','tam-guong-tieu-bieu',4,'Nữ chủ xưởng may vươn lên từ nghịch cảnh','nu-chu-xuong-may-vuon-len-tu-nghich-canh','Từng lầm lỡ, chị L.T.H nay là chủ một xưởng may nhỏ, tạo sinh kế cho nhiều phụ nữ có hoàn cảnh khó khăn.','<p>Chị L.T.H đã vượt qua mặc cảm, học nghề may trong thời gian cải tạo và ấp ủ giấc mơ khởi nghiệp.</p><p>Với sự đồng hành của cán bộ địa phương, chị mở xưởng may gia công nhận đơn hàng ổn định.</p><p>Xưởng may hiện là nơi làm việc của gần 15 chị em, lan tỏa nghị lực sống tích cực.</p>',NULL,'/assets/hero_banner.jpg','published',1,'2026-07-24 04:47:06','2026-07-24 20:47:06','2026-07-24 20:47:06'),(9,'role_model','tam-guong-tieu-bieu',4,'Chàng trai trẻ trở thành đầu bếp giỏi sau ngày hoàn lương','chang-trai-tre-tro-thanh-dau-bep-gioi','Nhờ chương trình đào tạo nghề, anh P.M.Q đã trở thành đầu bếp chính tại một nhà hàng lớn trong tỉnh.','<p>Sau khi tái hòa nhập, anh P.M.Q tham gia lớp học nghề nấu ăn miễn phí do chương trình hỗ trợ tổ chức.</p><p>Với sự chăm chỉ và năng khiếu, anh nhanh chóng thành thạo tay nghề và được nhận vào làm việc chính thức.</p><p>Câu chuyện của anh truyền cảm hứng cho nhiều bạn trẻ cùng cảnh ngộ.</p>',NULL,'/assets/hero_banner.jpg','published',1,'2026-07-23 20:47:06','2026-07-24 20:47:06','2026-07-24 20:47:06'),(10,'role_model','tam-guong-tieu-bieu',4,'Cựu phạm nhân trở thành tuyên truyền viên phòng chống tệ nạn','cuu-pham-nhan-tro-thanh-tuyen-truyen-vien','Bằng chính câu chuyện của mình, anh T.V.K tích cực tham gia tuyên truyền, giúp thanh thiếu niên tránh xa cám dỗ.','<p>Trải qua vấp ngã, anh T.V.K thấu hiểu giá trị của cơ hội thứ hai và mong muốn giúp đỡ người khác.</p><p>Anh trở thành tuyên truyền viên tích cực trong các buổi sinh hoạt cộng đồng về phòng chống tệ nạn xã hội.</p><p>Những chia sẻ chân thực của anh có sức thuyết phục lớn đối với giới trẻ địa phương.</p>',NULL,'/assets/hero_banner.jpg','published',1,'2026-07-23 04:47:06','2026-07-24 20:47:06','2026-07-24 20:47:06'),(11,'reintegration','mo-hinh-tai-hoa-nhap',5,'Mô hình hợp tác xã nông nghiệp thu hút người hoàn lương tham gia','mo-hinh-hop-tac-xa-nong-nghiep-hoan-luong','Hợp tác xã nông nghiệp sạch tạo môi trường lao động ổn định, giúp người hoàn lương có thu nhập bền vững.','<p>Hợp tác xã nông nghiệp sạch được thành lập với định hướng ưu tiên tiếp nhận lao động là người hoàn lương.</p><p>Các thành viên được hướng dẫn kỹ thuật canh tác hữu cơ và bao tiêu sản phẩm đầu ra.</p><p>Mô hình vừa mang lại hiệu quả kinh tế vừa góp phần giáo dục, cảm hóa người từng lầm lỡ.</p>',NULL,'/assets/hero_banner.jpg','published',1,'2026-07-24 10:47:06','2026-07-24 20:47:06','2026-07-24 20:47:06'),(12,'reintegration','mo-hinh-tai-hoa-nhap',5,'Doanh nghiệp xã hội nhận đào tạo và tuyển dụng người tái hòa nhập','doanh-nghiep-xa-hoi-dao-tao-tuyen-dung','Một doanh nghiệp xã hội cam kết dành 30% chỉ tiêu tuyển dụng cho người chấp hành xong án phạt tù.','<p>Doanh nghiệp xã hội này xây dựng quy trình đào tạo bài bản dành riêng cho lao động hoàn lương.</p><p>Người lao động được ký hợp đồng, đóng bảo hiểm và có cơ hội thăng tiến bình đẳng.</p><p>Đây là mô hình nhân văn cần được nhân rộng nhằm tạo cơ hội việc làm bền vững.</p>',NULL,'/assets/hero_banner.jpg','published',1,'2026-07-24 02:47:06','2026-07-24 20:47:06','2026-07-24 20:47:06'),(13,'reintegration','mo-hinh-tai-hoa-nhap',5,'Quỹ tín dụng cộng đồng hỗ trợ vốn khởi nghiệp cho người hoàn lương','quy-tin-dung-cong-dong-ho-tro-von-khoi-nghiep','Quỹ tín dụng cộng đồng cung cấp các khoản vay không lãi suất giúp người hoàn lương khởi sự kinh doanh nhỏ.','<p>Quỹ tín dụng cộng đồng được vận hành minh bạch với sự giám sát của chính quyền và các tổ chức đoàn thể.</p><p>Nhiều hộ gia đình đã sử dụng nguồn vốn để mở quán ăn, tiệm sửa xe và cửa hàng tạp hóa.</p><p>Mô hình góp phần giảm nghèo và ngăn ngừa nguy cơ tái phạm hiệu quả.</p>',NULL,'/assets/hero_banner.jpg','published',1,'2026-07-23 12:47:06','2026-07-24 20:47:06','2026-07-24 20:47:06'),(14,'document','van-ban-phap-luat',6,'Nghị định về các biện pháp bảo đảm tái hòa nhập cộng đồng','nghi-dinh-bien-phap-bao-dam-tai-hoa-nhap','Văn bản quy định chi tiết các biện pháp hỗ trợ, tạo điều kiện cho người chấp hành xong án phạt tù tái hòa nhập cộng đồng.','<p>Nghị định quy định rõ trách nhiệm của các cơ quan, tổ chức và chính quyền địa phương trong công tác tái hòa nhập cộng đồng.</p><p>Các biện pháp bao gồm hỗ trợ vay vốn, đào tạo nghề, giới thiệu việc làm và tư vấn tâm lý pháp lý.</p><p>Đây là cơ sở pháp lý quan trọng bảo đảm quyền lợi chính đáng của người hoàn lương.</p>',NULL,'/assets/hero_banner.jpg','published',1,'2026-07-24 14:47:06','2026-07-24 20:47:06','2026-07-24 20:47:06'),(15,'document','van-ban-phap-luat',6,'Thông tư hướng dẫn thủ tục xóa án tích theo quy định mới','thong-tu-huong-dan-thu-tuc-xoa-an-tich','Hướng dẫn cụ thể trình tự, thủ tục và hồ sơ đề nghị xóa án tích, tạo thuận lợi cho công dân.','<p>Thông tư quy định rõ các trường hợp đương nhiên được xóa án tích và thủ tục cấp phiếu lý lịch tư pháp.</p><p>Người dân được hướng dẫn chuẩn bị hồ sơ và nộp tại cơ quan có thẩm quyền một cách thuận tiện.</p><p>Quy định mới góp phần giảm bớt thủ tục hành chính, bảo đảm quyền công dân.</p>',NULL,'/assets/hero_banner.jpg','published',1,'2026-07-23 22:47:06','2026-07-24 20:47:06','2026-07-24 20:47:06'),(16,'document','van-ban-phap-luat',6,'Chỉ thị của Bộ Công an về tăng cường công tác hỗ trợ người hoàn lương','chi-thi-bo-cong-an-tang-cuong-ho-tro-hoan-luong','Chỉ thị yêu cầu công an các đơn vị, địa phương chủ động phối hợp hỗ trợ người tái hòa nhập cộng đồng.','<p>Chỉ thị nhấn mạnh vai trò nòng cốt của lực lượng công an trong công tác tái hòa nhập cộng đồng.</p><p>Các đơn vị được yêu cầu rà soát, nắm tình hình và kịp thời hỗ trợ người hoàn lương gặp khó khăn.</p><p>Đồng thời đẩy mạnh tuyên truyền, vận động doanh nghiệp và cộng đồng cùng chung tay.</p>',NULL,'/assets/hero_banner.jpg','published',1,'2026-07-23 00:47:06','2026-07-24 20:47:06','2026-07-24 20:47:06'),(17,'faq','hoi-dap-phap-luat',7,'Người chấp hành xong án phạt tù có được vay vốn ưu đãi không?','nguoi-chap-hanh-xong-an-phat-tu-vay-von-uu-dai','Giải đáp về điều kiện, thủ tục vay vốn ưu đãi dành cho người chấp hành xong án phạt tù để phát triển kinh tế.','<p><strong>Hỏi:</strong> Tôi vừa chấp hành xong án phạt tù, tôi có được vay vốn ưu đãi để làm ăn không?</p><p><strong>Đáp:</strong> Theo quy định hiện hành, người chấp hành xong án phạt tù có nhu cầu và đủ điều kiện được xem xét vay vốn ưu đãi từ Ngân hàng Chính sách xã hội.</p><p>Bạn cần liên hệ UBND cấp xã nơi cư trú để được hướng dẫn lập hồ sơ và xác nhận theo quy định.</p>',NULL,'/assets/hero_banner.jpg','published',1,'2026-07-24 06:47:06','2026-07-24 20:47:06','2026-07-24 20:47:06'),(18,'faq','hoi-dap-phap-luat',7,'Thủ tục xin cấp phiếu lý lịch tư pháp được thực hiện như thế nào?','thu-tuc-xin-cap-phieu-ly-lich-tu-phap','Hướng dẫn công dân về hồ sơ, nơi nộp và thời gian giải quyết cấp phiếu lý lịch tư pháp.','<p><strong>Hỏi:</strong> Tôi cần xin phiếu lý lịch tư pháp để đi làm, thủ tục gồm những gì?</p><p><strong>Đáp:</strong> Bạn chuẩn bị tờ khai yêu cầu cấp phiếu lý lịch tư pháp, bản sao căn cước công dân và các giấy tờ liên quan.</p><p>Hồ sơ được nộp tại Sở Tư pháp nơi thường trú; thời gian giải quyết thông thường không quá 10 ngày làm việc.</p>',NULL,'/assets/hero_banner.jpg','published',1,'2026-07-23 14:47:06','2026-07-24 20:47:06','2026-07-24 20:47:06');
