INSERT INTO `page_blocks` VALUES (23,1,'hero',1,'{\"badge\": \"\", \"title\": \"Đồng hành cùng hành trình hướng thiện\", \"bgImage\": \"/assets/hero_banner.jpg\", \"btnHelp\": true, \"btnAbout\": true, \"subtitle\": \"Nền tảng hỗ trợ toàn diện về nghề nghiệp, pháp lý và tư vấn tâm lý\"}',1,'2026-07-24 11:37:50',1),(24,1,'stats',2,'{\"stats\": [{\"label\": \"Tỉnh / Thành phố đồng hành\", \"value\": \"34\"}, {\"label\": \"Người hoàn lương được hỗ trợ\", \"value\": \"10.000+\"}, {\"label\": \"Mô hình kinh tế tiêu biểu\", \"value\": \"500+\"}, {\"label\": \"Tư vấn pháp lý & Tâm lý miễn phí\", \"value\": \"24/7\"}]}',1,'2026-07-24 11:37:50',1),(25,1,'news',3,'{\"title\": \"Tin nổi bật\", \"maxItems\": 5}',1,'2026-07-24 11:37:50',1),(26,1,'role_models',4,'{\"title\": \"Tấm Gương Tiêu Biểu\", \"maxItems\": 3, \"subtitle\": \"Nghị lực vươn lên\"}',1,'2026-07-24 11:37:50',1),(27,1,'reintegration',6,'{\"title\": \"Mô Hình Tái Hòa Nhập\", \"maxItems\": 3, \"subtitle\": \"Sinh kế bền vững\"}',1,'2026-07-24 20:44:55',1),(28,1,'documents',7,'{\"title\": \"Văn bản Pháp luật Mới ban hành\", \"maxItems\": 6}',1,'2026-07-24 20:44:55',1),(29,1,'support_form',8,'{\"title\": \"Đăng Ký Tư Vấn & Hỗ Trợ Tái Hòa Nhập\"}',1,'2026-07-24 20:44:55',1),(30,1,'links',9,'{\"title\": \"Liên Kết Hữu Ích\"}',1,'2026-07-24 20:44:55',1),(33,3,'heading',1,'{\"text\": \"Liên hệ & Trợ giúp\", \"align\": \"center\", \"bgImage\": \"/assets/hero_banner.jpg\", \"variant\": \"banner\", \"subtitle\": \"Hotline 0903.480.985 — Tiếp nhận yêu cầu trợ giúp 24/7\"}',1,'2026-07-24 12:05:11',NULL),(34,3,'contact_form',2,'{\"title\": \"Gửi yêu cầu trợ giúp\", \"infoRows\": [{\"label\": \"Đơn vị chủ quản:\", \"value\": \"Cục Cảnh sát quản lý tạm giữ, tạm giam và thi hành án hình sự tại cộng đồng (C11) - Bộ Công an\"}, {\"label\": \"Địa chỉ:\", \"value\": \"Thôn Phượng Mỹ, xã Tam Hưng, thành phố Hà Nội\"}, {\"label\": \"Hotline:\", \"value\": \"0903.480.985\"}, {\"label\": \"Email:\", \"value\": \"contact@conduonghuongthien.com.vn\"}], \"noteText\": \"Hệ thống trợ giúp tiếp nhận yêu cầu 24/7 từ người chấp hành xong án phạt tù hoặc thân nhân của họ. Sau khi tiếp nhận thông tin, Ban Biên tập sẽ tiến hành bảo mật dữ liệu cá nhân, phân loại nghiệp vụ và chuyển giao nhanh chóng đến lực lượng Công an cấp cơ sở (xã, phường, thị trấn) hoặc ban ngành liên quan tại địa bàn bạn cư trú để hỗ trợ xử lý kịp thời.\", \"showInfo\": true, \"infoTitle\": \"Thông tin Ban Biên tập\", \"noteTitle\": \"Cơ chế trợ giúp\"}',1,'2026-07-24 12:05:11',NULL),(35,2,'heading',1,'{\"text\": \"Giới thiệu\", \"align\": \"center\", \"bgImage\": \"/assets/hero_banner.jpg\", \"variant\": \"banner\", \"subtitle\": \"Ban Biên tập Cổng thông tin Con Đường Hướng Thiện\"}',1,'2026-07-24 13:10:43',NULL),(36,2,'content_aside',2,'{\"icon\": \"fa-solid fa-building-columns\", \"title\": \"Ban Biên tập\", \"bodyHtml\": \"<h3>Mục đích hoạt động</h3><p>Trang thông tin điện tử <strong>Con Đường Hướng Thiện</strong> hoạt động dưới sự chỉ đạo của Cục Cảnh sát quản lý tạm giữ, tạm giam và thi hành án hình sự tại cộng đồng (C11) - Bộ Công an.</p><p>Mục tiêu tối thượng của nền tảng là cung cấp thông tin chính thống về các chính sách, nghị định của Đảng và Nhà nước liên quan đến công tác thi hành án hình sự và hỗ trợ hòa nhập cộng đồng; tuyên truyền, nhân rộng các mô hình sản xuất kinh tế hiệu quả, các tấm gương điển hình tiên tiến hoàn lương lập nghiệp thành công; định hướng tư tưởng, pháp lý và kết nối hỗ trợ trực tuyến 24/7 giúp người lầm lỡ xóa bỏ tự ti, sớm ổn định cuộc sống.</p><h3>Nhiệm vụ trọng tâm</h3><ul><li><strong>Tuyên truyền &amp; Giáo dục pháp luật:</strong> Phổ biến các quy định về xóa án tích, chính sách vay vốn ưu đãi, quyền và nghĩa vụ công dân giúp người hoàn lương nâng cao hiểu biết pháp lý.</li><li><strong>Đào tạo &amp; Hướng nghiệp:</strong> Kết nối các cơ sở đào tạo nghề và các doanh nghiệp nhân văn nhằm tổ chức các lớp học nghề, tạo cơ hội việc làm công bằng cho người lầm lỡ.</li><li><strong>Tư vấn &amp; Trợ giúp trực tuyến:</strong> Xây dựng hệ thống giải đáp tự động và đường dây nóng tiếp nhận thông tin đăng ký hỗ trợ trực tiếp 24/7 trên phạm vi cả nước.</li></ul>\", \"asideNote\": \"Ban Biên Tập: Đại diện Cảnh sát Thi hành án hình sự & Hỗ trợ tư pháp công an các địa phương.\", \"asideLabel\": \"ĐƠN VỊ CHỦ QUẢN\", \"asideTitle\": \"Cục Cảnh sát QLTHG, TG và THAHS tại cộng đồng (C11)\", \"asideSubtitle\": \"Bộ Công an\", \"highlightLabel\": \"Hotline liên hệ trực tiếp:\", \"highlightValue\": \"0903.480.985\"}',1,'2026-07-24 13:10:43',NULL),(37,1,'quote',5,'{\"cite\": \"— Đề án Tái hòa nhập cộng đồng, C11 Bộ Công an\", \"quote\": \"Mỗi con người lầm lỡ đều xứng đáng có một cơ hội thứ hai để hướng thiện. Sự chung tay, đồng hành của gia đình và toàn xã hội chính là ánh dương thắp sáng nẻo về lương thiện.\", \"bgImage\": \"/assets/hero_banner.jpg\"}',1,'2026-07-24 20:49:41',NULL);
/*!40000 ALTER TABLE `page_blocks` ENABLE KEYS */;
